 }
 // MT memusage
 lzma_options_lzma opt; lzma_lzma_preset(&opt,6);
 lzma_filter f[2]={{LZMA_FILTER_LZMA2,&opt},{LZMA_VLI_UNKNOWN,NULL}};
 lzma_mt mt={0}; mt.filters=f; mt.check=LZMA_CHECK_CRC64;
 for(int t=1;t<=8;t++){ mt.threads=t; mt.block_size=0; mt.timeout=0; printf("mt threads %d mem %llu\n",t,(unsigned long long)lzma_stream_encoder_mt_memusage(&mt));}
 return 0;
}
