import subprocess, struct, lzma, os
os.chdir('/tmp/C1')
def transform(data, filt='riscv', start=0):
    open('in.bin','wb').write(data)
    spec=f'{filt}:start={start}' if start else filt
    subprocess.run(['/workspace/executable','-T1','--filters',f'{spec} lzma2','-cf','in.bin'], stdout=open('out.xz','wb'), check=True)
    xz=open('out.xz','rb').read(); bh=(xz[12]+1)*4; d=lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=[{"id":lzma.FILTER_LZMA2,"preset":6}])
    return d.decompress(xz[12+bh:])
def jal(offset, rd=1):
    return (((offset>>20)&1)<<31)|(((offset>>1)&0x3ff)<<21)|(((offset>>11)&1)<<20)|(((offset>>12)&0xff)<<12)|(rd<<7)|0x6f
def words(ws): return b''.join(struct.pack('<I',w) for w in ws)
def unwords(b): return [struct.unpack('<I',b[i:i+4])[0] for i in range(0,len(b),4)]
for st,off in [(0,0),(1<<21,0),((1<<21)+16,0),(1<<22,0),(1<<31,0),(-16 & 0xffffffff,0),(0,-4),(4096,-8192),(0,1048574),(0,-1048576)]:
 data=words([jal(off,1)])+b'\x00'*16
 try:
  out=transform(data,start=st); w=unwords(out)[0]; print(f"start {st:#x} off {off} in {jal(off,1):08x} out {w:08x}")
 except Exception as e: print(st,off,e)
# AUIPC+JALR pair tests
def auipc(rd,imm20):
 # U type: imm in bits31-12, rd, opcode 0x17
 return ((imm20 & 0xfffff)<<12)|(rd<<7)|0x17
def jalr(rd,rs1,off12):
 return (((off12 & 0xfff)<<20)|(rs1<<15)|(0<<12)|(rd<<7)|0x67)
print('auipc+jalr')
for pair in [(auipc(1,0),jalr(1,1,0)),(auipc(1,1),jalr(1,1,16)),(auipc(5,2),jalr(5,5,-16)),(auipc(1,0),jalr(0,1,8))]:
 data=words(list(pair))+b'\x00'*16
 out=transform(data); print([hex(x) for x in unwords(data)],'->',[hex(x) for x in unwords(out)][:2])
# position 8192 pairs
data=b'\x00'*8192+words([auipc(1,0),jalr(1,1,0)])
out=transform(data); print('at8192 pair ->',[hex(x) for x in unwords(out[8192:8192+8])])
# C.JAL / C.J compressed instructions (16-bit)
def u16(ws): return b''.join(struct.pack('<H',w) for w in ws)
# CJ offset encoding is complex; test raw sequences later
PY
