// Reimplementation of an xz-compatible command line tool.
// Written from scratch based on observed command-line behaviour.
// Uses liblzma for the core LZMA/XZ codecs.
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdarg.h>
#include <ctype.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <getopt.h>
#include <limits.h>
#include <math.h>
#include <poll.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <utime.h>
#include <lzma.h>

// ---------- globals ----------
static const char *progname = "xz";
static int verbosity = 0; // >0 verbose, 0 normal, -1 quiet, -2 qq
static int exit_status = 0; // 0, 1 error, 2 warning
static bool opt_no_warn = false;
static bool opt_robot = false;

static void *xmalloc(size_t n) {
    if (n == 0) n = 1;
    void *p = malloc(n);
    if (!p) { fprintf(stderr, "%s: Cannot allocate memory\n", progname); exit(1); }
    return p;
}
static void *xrealloc(void *p, size_t n) {
    if (n == 0) n = 1;
    void *q = realloc(p, n);
    if (!q) { fprintf(stderr, "%s: Cannot allocate memory\n", progname); exit(1); }
    return q;
}
static char *xstrdup(const char *s) { if (!s) return NULL; char *p = xmalloc(strlen(s)+1); strcpy(p, s); return p; }
static char *xstrndup(const char *s, size_t n) { char *p = xmalloc(n+1); memcpy(p,s,n); p[n]=0; return p; }

static void set_exit_error(void) { exit_status = 1; }
static void set_exit_warning(void) { if (exit_status == 0 && !opt_no_warn) exit_status = 2; }

// Message helpers. Error messages are shown unless verbosity <= -2.
// Warnings are shown unless verbosity <= -1.
static void msg_error(const char *fmt, ...) {
    set_exit_error();
    if (verbosity < -1) return;
    va_list ap; va_start(ap, fmt);
    fprintf(stderr, "%s: ", progname);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}
static void msg_error_noexit(const char *fmt, ...) {
    // like msg_error but caller manages exit status (already set)
    if (verbosity < -1) return;
    va_list ap; va_start(ap, fmt);
    fprintf(stderr, "%s: ", progname);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}
static void msg_warning(const char *fmt, ...) {
    if (verbosity < 0) return;
    va_list ap; va_start(ap, fmt);
    fprintf(stderr, "%s: ", progname);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}
// warnings that affect exit status
static void msg_warning_exit(const char *fmt, ...) {
    set_exit_warning();
    if (verbosity < 0) return;
    va_list ap; va_start(ap, fmt);
    fprintf(stderr, "%s: ", progname);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}
static void msg_info(const char *fmt, ...) { // -vv
    if (verbosity < 2) return;
    va_list ap; va_start(ap, fmt);
    fprintf(stderr, "%s: ", progname);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}
static void msg_try_help(void) {
    if (verbosity < 0) return;
    fprintf(stderr, "%s: Try '%s --help' for more information.\n", progname, progname);
}
static void fatal_error(const char *fmt, ...) {
    set_exit_error();
    if (verbosity >= -1) {
        va_list ap; va_start(ap, fmt);
        fprintf(stderr, "%s: ", progname);
        vfprintf(stderr, fmt, ap);
        fputc('\n', stderr);
        va_end(ap);
    }
    exit(1);
}

// ---------- formatting helpers ----------
static uint64_t total_ram_bytes(void) {
    long pages = sysconf(_SC_PHYS_PAGES);
    long psz = sysconf(_SC_PAGESIZE);
    if (pages <= 0 || psz <= 0) return 0;
    return (uint64_t)pages * (uint64_t)psz;
}
static uint32_t hardware_threads(void) {
    uint32_t t = lzma_cputhreads();
    if (t == 0) t = 1;
    return t;
}
static void fmt_u64(char *buf, size_t bufsz, uint64_t v) { snprintf(buf, bufsz, "%llu", (unsigned long long)v); }
static uint64_t ceil_mib(uint64_t v) { return (v + 1048575ULL) / 1048576ULL; }
static void fmt_mem_mib(char *buf, size_t sz, uint64_t v) { snprintf(buf, sz, "%llu MiB", (unsigned long long)ceil_mib(v)); }
// for "The limit is %s."
static void fmt_mem_limit(char *buf, size_t sz, uint64_t v) {
    if (v < 1048576ULL) snprintf(buf, sz, "%llu B", (unsigned long long)v);
    else snprintf(buf, sz, "%llu MiB", (unsigned long long)ceil_mib(v));
}
// human readable size (as in -l and progress)
static void fmt_human(char *buf, size_t sz, uint64_t size) {
    if (size < 10000ULL) { snprintf(buf, sz, "%llu B", (unsigned long long)size); return; }
    static const char *units[] = {"KiB","MiB","GiB","TiB","PiB","EiB"};
    double v = (double)size;
    int u = -1;
    while (v >= 10000.0 && u < 5) { v /= 1024.0; u++; }
    if (u < 0) { snprintf(buf, sz, "%llu B", (unsigned long long)size); return; }
    snprintf(buf, sz, "%.1f %s", v, units[u]);
}
static void fmt_human_with_bytes(char *buf, size_t sz, uint64_t size) {
    char h[64]; fmt_human(h, sizeof h, size);
    if (size < 10000ULL) snprintf(buf, sz, "%s", h);
    else snprintf(buf, sz, "%s (%llu B)", h, (unsigned long long)size);
}
static void fmt_dict(char *buf, size_t sz, uint64_t dict) {
    if (dict % 1048576ULL == 0) snprintf(buf, sz, "%lluMiB", (unsigned long long)(dict/1048576ULL));
    else if (dict % 1024ULL == 0) snprintf(buf, sz, "%lluKiB", (unsigned long long)(dict/1024ULL));
    else snprintf(buf, sz, "%llu", (unsigned long long)dict);
}
static void fmt_ratio(char *buf, size_t sz, uint64_t comp, uint64_t uncomp) {
    if (uncomp == 0) { snprintf(buf, sz, "---"); return; }
    double r = (double)comp / (double)uncomp;
    if (r > 9.999) { snprintf(buf, sz, "---"); return; }
    snprintf(buf, sz, "%.3f", r);
}
// ratio for progress: returns op char and fills buf with number
static char fmt_ratio_progress(char *buf, size_t sz, uint64_t comp, uint64_t uncomp) {
    if (uncomp == 0) { snprintf(buf, sz, "9.999"); return '>'; }
    double r = (double)comp / (double)uncomp;
    if (r > 9.999) { snprintf(buf, sz, "9.999"); return '>'; }
    snprintf(buf, sz, "%.3f", r);
    return '=';
}

EOF
cat /workspace/src/main.c | wc -l"}

