static bool suffix_multiplier(const char *s, uint64_t *mult) {
    // allowed: K/M/G (any case) optionally 'i', optionally 'B' (uppercase)
    size_t n = strlen(s);
    if (n < 1 || n > 3) return false;
    int idx;
    char c0 = s[0];
    if (c0=='K'||c0=='k') idx=1; else if (c0=='M'||c0=='m') idx=2; else if (c0=='G'||c0=='g') idx=3; else return false;
    if (n==2) {
        if (!(s[1]=='B' || s[1]=='i')) return false;
    } else if (n==3) {
        if (!(s[1]=='i' && s[2]=='B')) return false;
