// core parse for a NUL-terminated token; on error calls fatal_error style and exits
static uint64_t parse_number_or_die(const char *optname, const char *value, uint64_t minv, uint64_t maxv) {
    const char *p = value;
    while (*p && isspace((unsigned char)*p)) p++;
    if (!isdigit((unsigned char)*p)) {
        fatal_error("%s: Value is not a non-negative decimal integer", p);
    }
    uint64_t result = 0;
    bool overflow = false;
    while (isdigit((unsigned char)*p)) {
        unsigned int digit = *p - '0';
        if (result > (UINT64_MAX - digit)/10) overflow = true;
        if (!overflow) result = result*10 + digit; else result = UINT64_MAX;
        p++;
    }
    if (*p) {
        const char *suffix_start = p;
        uint64_t mult;
        // suffix must consume the whole remainder
        if (!suffix_multiplier(suffix_start, &mult)) {
            if (verbosity >= -1) {
                msg_error_noexit("%s: Invalid multiplier suffix", suffix_start);
                msg_error_noexit("Valid suffixes are 'KiB' (2^10), 'MiB' (2^20), and 'GiB' (2^30).");
            } else {
                set_exit_error();
            }
            exit(1);
        }
        // multiply with saturation
        if (result > UINT64_MAX / mult) result = UINT64_MAX; else result *= mult;
    }
    if (result < minv || result > maxv) {
        char mn[32], mx[32]; fmt_u64(mn,sizeof mn,minv); fmt_u64(mx,sizeof mx,maxv);
        fatal_error("Value of the option '%s' must be in the range [%s, %s]", optname, mn, mx);
    }
    return result;
}
// memlimit parsing (handles trailing %)
static uint64_t parse_memlimit_or_die(const char *optname, const char *value) {
    char *copy = xstrdup(value);
    size_t len = strlen(copy);
    bool percent = false;
    char namebuf[64];
    snprintf(namebuf, sizeof namebuf, "%s", optname);
    if (len > 0 && copy[len-1]=='%') { percent = true; copy[len-1]=0; snprintf(namebuf, sizeof namebuf, "%s%%", optname); }
    uint64_t v;
    if (percent) {
        v = parse_number_or_die(namebuf, copy, 1, 100);
        uint64_t ram = total_ram_bytes();
        // ram * v / 100, avoid overflow using 128
        unsigned __int128 calc = (unsigned __int128)ram * v / 100;
        free(copy);
        return (uint64_t)calc;
    } else {
        v = parse_number_or_die(namebuf, copy, 0, UINT64_MAX);
        free(copy);
        return v;
    }
}

