} FiltersParseResult;
static const char *filters_opt_display = "--filters"; // for error header, set before call
static void filters_string_error(const char *str, size_t pos, const char *msg) {
    set_exit_error();
    if (verbosity >= -1) {
        msg_error_noexit("Error in %s=FILTERS option:", filters_opt_display);
        msg_error_noexit("%s", str);
        // caret line
        char *caret = xmalloc(pos+2);
        memset(caret,' ',pos); caret[pos]='^'; caret[pos+1]=0;
        msg_error_noexit("%s", caret);
        free(caret);
        msg_error_noexit("%s", msg);
    }
    exit(1);
}
// helper numeric parse inside filters string: returns value, on error calls filters_string_error
static uint64_t filters_parse_number(const char *str, size_t value_start, size_t value_end, uint64_t minv, uint64_t maxv, size_t *consumed_end) {
    // value is str[value_start:value_end) but caller gives extent scanning
    // This function parses digits starting at value_start, then optional suffix, within the whole string.
    // Delimiters for the value are ',', ' ', '-', or end; implemented by caller passing parsing state.
    (void)minv; (void)maxv; (void)value_end; (void)consumed_end; (void)str; (void)value_start;
    return 0;
}
// We implement parser as a function over the whole string with index pointer.
typedef struct {
    const char *s;
    size_t len;
    size_t i;
    const char *display;
    bool disallow_lzma1;
} FParser;
static void fp_error(FParser *fp, size_t pos, const char *msg) {
    filters_opt_display = fp->display;
    filters_string_error(fp->s, pos, msg);
}
static uint64_t fp_parse_uint(FParser *fp, uint64_t minv, uint64_t maxv) {
    size_t vstart = fp->i;
    if (fp->i >= fp->len || !isdigit((unsigned char)fp->s[fp->i])) {
        fp_error(fp, vstart, "Value is not a non-negative decimal integer");
    }
    uint64_t result = 0; bool ov=false;
    while (fp->i < fp->len && isdigit((unsigned char)fp->s[fp->i])) {
        unsigned d = fp->s[fp->i]-'0';
        if (result > (UINT64_MAX-d)/10) ov=true;
        if (!ov) result=result*10+d; else result=UINT64_MAX;
        fp->i++;
    }
    // suffix
    if (fp->i < fp->len && isalpha((unsigned char)fp->s[fp->i])) {
        size_t sstart = fp->i;
        while (fp->i < fp->len && isalpha((unsigned char)fp->s[fp->i])) fp->i++;
        char *suffix = xstrndup(fp->s+sstart, fp->i-sstart);
        uint64_t mult;
        if (!suffix_multiplier(suffix, &mult)) {
            free(suffix);
            fp_error(fp, sstart, "Invalid multiplier suffix (KiB, MiB, or GiB)");
        }
        free(suffix);
        if (result > UINT64_MAX/mult) result=UINT64_MAX; else result*=mult;
        // after suffix, next char must be delimiter , space - or end; otherwise invalid suffix
        if (fp->i < fp->len && !(fp->s[fp->i]==',' || fp->s[fp->i]==' ' || fp->s[fp->i]=='-')) {
            fp_error(fp, sstart, "Invalid multiplier suffix (KiB, MiB, or GiB)");
        }
    } else if (fp->i < fp->len && !(fp->s[fp->i]==',' || fp->s[fp->i]==' ' || fp->s[fp->i]=='-' )) {
        // characters like ':' directly after digits are treated as suffix error at suffix position
        // For consistency: position is fp->i (first suffix char)
        // Only if this is not part of option parsing terminators - handled by caller for other cases.
        // We'll treat ':' as invalid suffix
        if (fp->s[fp->i]==':') {
            fp_error(fp, fp->i, "Invalid multiplier suffix (KiB, MiB, or GiB)");
        }
    }
    if (result < minv || result > maxv) {
        fp_error(fp, vstart, "Value out of range");
    }
    return result;
}
static FiltersParseResult parse_filters_string(const char *str, const char *display, bool disallow_lzma1) {
    FiltersParseResult res; memset(&res,0,sizeof res);
    FParser fp; fp.s=str; fp.len=strlen(str); fp.i=0; fp.display=display; fp.disallow_lzma1=disallow_lzma1;
    // skip spaces
    while (fp.i < fp.len && fp.s[fp.i]==' ') fp.i++;
