        if (fp.i < fp.len && fp.s[fp.i]!=' ') {
            fp_error(&fp, fp.i, "Unsupported flag in the preset");
        }
        // trailing: skip spaces, if any content -> Unsupported preset at start
        while (fp.i < fp.len && fp.s[fp.i]==' ') fp.i++;
        if (fp.i < fp.len) fp_error(&fp, start, "Unsupported preset");
