            if (fp.i >= fp.len || fp.s[fp.i]==' ') fp_error(&fp, name_start, "Filter name is missing");
            else {
                // read token until space or ':'
                size_t ts=fp.i;
                while (fp.i < fp.len && fp.s[fp.i]!=' ' && fp.s[fp.i]!=':') fp.i++;
                (void)ts;
                fp_error(&fp, name_start, "Unknown filter name");
            }
        }
        char *name = xstrndup(fp.s+ns, fp.i-ns);
