                    if (strcmp(v,"hc3")==0) fs->lzma.mf=LZMA_MF_HC3; else if (strcmp(v,"hc4")==0) fs->lzma.mf=LZMA_MF_HC4; else if (strcmp(v,"bt2")==0) fs->lzma.mf=LZMA_MF_BT2; else if (strcmp(v,"bt3")==0) fs->lzma.mf=LZMA_MF_BT3; else if (strcmp(v,"bt4")==0) fs->lzma.mf=LZMA_MF_BT4; else { free(v); free(oname); fp_error(&fp, vstart, "Invalid option value"); }
