                        else if (strcmp(oname,"lc")==0) fs->lzma.lc=(uint32_t)val;
                        else if (strcmp(oname,"lp")==0) fs->lzma.lp=(uint32_t)val;
                        else if (strcmp(oname,"pb")==0) fs->lzma.pb=(uint32_t)val;
                        else if (strcmp(oname,"nice")==0) fs->lzma.nice_len=(uint32_t)val;
                        else if (strcmp(oname,"depth")==0) fs->lzma.depth=(uint32_t)val;
                    } else if (fid==0x03) fs->dist=(uint32_t)val;
                    else if (is_bcj_id(fid)) fs->start_offset=(uint32_t)val;
