// ---------- dynamic buffer ----------
typedef struct { uint8_t *data; size_t len; size_t cap; } Buffer;
static void buf_init(Buffer *b){ b->data=NULL; b->len=0; b->cap=0; }
static void buf_free(Buffer *b){ free(b->data); b->data=NULL; b->len=b->cap=0; }
static void buf_reserve(Buffer *b, size_t need){
    if (b->cap >= need) return;
    size_t nc = b->cap ? b->cap : 256;
