        v |= (uint64_t)(b&0x7F)<<shift;
        if (!(b&0x80)) break;
        // next byte must not be zero (canonical check as in spec decoder)
        if (i< len && data[i]==0) {} // spec's code checks in loop; we approximate
        shift+=7;
        if (shift>=63) { /* still allow up to 9 bytes */ }
