        // peek buffer is only for unread bytes start at pos; if pos>0, compact
        if (in->peek_pos>0) {
            size_t rem = in->peek_len - in->peek_pos;
            memmove(in->peek, in->peek+in->peek_pos, rem); in->peek_len=rem; in->peek_pos=0;
