        if(!lz) return UINT64_MAX;
        // chain structure check: lzma must be last
        if (&s[n-1]!=lz) return UINT64_MAX;
        LibFilters lf; FilterSpec one=*lz; if(!build_lib_filters(&one,1,&lf)) return UINT64_MAX;
