        // approximate using lzma only chain for mt memusage (bcj adds little per thread - earlier observed same MiB)
        // To get close, compute mt memusage with a chain comprising [lzma] only and adjust
        FilterSpec *lz=chain_find_lzma(resolved_specs[0], resolved_counts[0]);
        if(!lz) return UINT64_MAX;
        FilterSpec one=*lz; LibFilters lf2; build_lib_filters(&one,1,&lf2);
        lzma_mt mt; memset(&mt,0,sizeof mt); mt.filters=lf2.filters; mt.check=opt_check; mt.threads=threads; mt.block_size=block_size;
        return lzma_stream_encoder_mt_memusage(&mt);
    }
    if(!build_lib_filters(resolved_specs[0], resolved_counts[0], &lf)) return UINT64_MAX;
    lzma_mt mt; memset(&mt,0,sizeof mt); mt.filters=lf.filters; mt.check=opt_check; mt.threads=threads; mt.block_size=block_size;
    return lzma_stream_encoder_mt_memusage(&mt);
}
static uint64_t effective_mt_block_size_for_mem(void){
    if (opt_block_size_set) return opt_block_size;
    if (opt_block_list_set) {
        // if any entry size ==0 => 0
        uint64_t mx=0; bool has_zero=false;
        for(size_t i=0;i<opt_block_list_len;i++){ if(opt_block_list[i].size==0) has_zero=true; else if(opt_block_list[i].size>mx) mx=opt_block_list[i].size; }
        if (has_zero) return 0;
        FilterSpec *lz=chain_find_lzma(resolved_specs[0], resolved_counts[0]);
        uint64_t dict = lz ? lz->lzma.dict_size : 0;
        uint64_t cap = dict*3;
        if (cap && mx>cap) return cap;
        return mx;
    }
    return 0;
}

