                if (userlim) {
                    if (opt_no_adjust) mem_too_low_die(memusage, userlim);
                    msg_warning("Switching to single-threaded mode to not exceed the memory usage limit of %llu MiB", (unsigned long long)ceil_mib(userlim));
                    enc_is_mt_real=false; enc_threads_resolved=1; switched_to_single=true;
                } else {
                    msg_warning("Switching to single-threaded mode to not exceed the memory usage limit of %llu MiB", (unsigned long long)ceil_mib(limit_for_reduction));
                    enc_is_mt_real=false; enc_threads_resolved=1; switched_to_single=true;
                }
            }
        }
    }
