        // also if any used chain contains custom bcj
        for(int idx=0;idx<10;idx++) if(chain_is_used[idx] && chain_contains_custom_bcj(resolved_specs[idx], resolved_counts[idx])) enc_use_manual_xz=true;
    }
}

