    if ((opt_mode==MODE_COMPRESS||opt_mode==MODE_DECOMPRESS) && opt_format==FMT_RAW && !opt_suffix && !opt_stdout) {
        bool any=false;
        if (opt_files_set) any=true;
        else for(int i=0;i<cli_files_count;i++) if(strcmp(cli_files[i],"-")!=0) any=true;
        if (any) fatal_error("With --format=raw, --suffix=.SUF is required unless writing to stdout");
    }
    if (opt_mode==MODE_LIST) return;
