    if (opt_mode==MODE_COMPRESS && eff==FMT_XZ && opt_block_list_set) {
        for(size_t i=0;i<opt_block_list_len;i++){
            int cn=opt_block_list[i].chain;
            if(cn!=0 && !chains[cn].present) fatal_error("filter chain %d used by --block-list but not specified with --filters%d=", cn, cn);
        }
    }
    // raw preset warning
    if (opt_format==FMT_RAW && !chains[0].present) {
        msg_warning("Using a preset in raw mode is discouraged.");
        msg_warning("The exact options of the presets may vary between software versions.");
    }
    if (opt_mode==MODE_DECOMPRESS || opt_mode==MODE_TEST) {
        if (opt_format==FMT_RAW) {
            uint64_t decmem = compute_raw_decoder_memusage(resolved_specs[0], resolved_counts[0]);
            if (decmem==UINT64_MAX) fatal_error("Unsupported filter chain or filter options");
            if (memlimit_decompress!=0 && decmem>memlimit_decompress) mem_too_low_die(decmem, memlimit_decompress);
        }
        if (opt_robot) fatal_error("Compression and decompression with --robot are not supported yet.");
        return;
    }
    // ---- compress init ----
    // filter chain print
    bool alt_used=false;
    if (opt_block_list_set) for(size_t i=0;i<opt_block_list_len;i++) if(opt_block_list[i].chain!=0) alt_used=true;
    if (!alt_used && verbosity>=2) {
        char *cs = format_filter_chain_str(resolved_specs[0], resolved_counts[0], true);
        msg_info("Filter chain: %s", cs);
        free(cs);
    }
    // flush compatibility
    if (opt_flush_timeout!=0) {
        for(int idx=0;idx<10;idx++) if(chain_is_used[idx]){
            // chain must be present or 0
            for(int i=0;i<resolved_counts[idx];i++){
                uint64_t fid=resolved_specs[idx][i].id;
                if (is_bcj_id(fid) || fid==LZMA_FILTER_LZMA1) {
                    fatal_error("Filter chain %d is incompatible with --flush-timeout", idx);
                }
            }
        }
    }
    enc_threads_resolved = opt_threads_value==0 ? hardware_threads() : (uint32_t)opt_threads_value;
    enc_mt_candidate = (opt_threads_value != 1) || opt_threads_plus;
    if (opt_flush_timeout!=0 && enc_mt_candidate) {
        msg_warning("Switching to single-threaded mode due to --flush-timeout");
        enc_mt_candidate=false; enc_threads_resolved=1;
    }
    enc_is_mt_real = (eff==FMT_XZ && enc_mt_candidate);
    // MT chain check for LZMA2 presence
    if (enc_is_mt_real) {
        for(int idx=0;idx<10;idx++) if(chain_is_used[idx]){
            if (!chain_has_lzma(resolved_specs[idx], resolved_counts[idx], LZMA_FILTER_LZMA2))
                fatal_error("Unsupported options in filter chain %d", idx);
        }
    }
    uint64_t mt_block = effective_mt_block_size_for_mem();
    uint64_t memusage;
    if (enc_is_mt_real) {
        enc_mt_memusage = compute_mt_memusage(enc_threads_resolved, mt_block);
        memusage = enc_mt_memusage;
    } else {
        enc_single_memusage = compute_raw_encoder_memusage(resolved_specs[0], resolved_counts[0]);
        memusage = enc_single_memusage;
    }
    enc_decoder_memusage = compute_raw_decoder_memusage(resolved_specs[0], resolved_counts[0]);
    if (memusage==UINT64_MAX || enc_decoder_memusage==UINT64_MAX) fatal_error("Unsupported filter chain or filter options");
    if (enc_is_mt_real && verbosity>=2) msg_info("Using up to %u threads.", enc_threads_resolved);
    if (verbosity>=2) {
        char second[128];
        if (memlimit_compress==0) snprintf(second,sizeof second,"The limiter is disabled.");
        else { char lb[64]; fmt_mem_limit(lb,sizeof lb,memlimit_compress); snprintf(second,sizeof second,"The limit is %s.", lb); }
        msg_info("%llu MiB of memory is required. %s", (unsigned long long)ceil_mib(memusage), second);
        msg_info("Decompression will need %llu MiB of memory.", (unsigned long long)ceil_mib(enc_decoder_memusage));
    }
    // memory limit handling
    uint64_t userlim = memlimit_compress;
    bool switched_to_single=false;
    if (enc_is_mt_real) {
        uint64_t limit_for_reduction=0;
        bool is_zero = (opt_threads_value==0);
        if (is_zero) limit_for_reduction = userlim ? userlim : (total_ram_bytes()/4);
        else limit_for_reduction = userlim;
        if (limit_for_reduction && memusage > limit_for_reduction) {
            uint32_t orig_threads = enc_threads_resolved;
            while (enc_threads_resolved>1 && memusage > limit_for_reduction) {
                enc_threads_resolved--;
                memusage = compute_mt_memusage(enc_threads_resolved, mt_block);
                if (memusage==UINT64_MAX) fatal_error("Unsupported filter chain or filter options");
            }
            if (memusage <= limit_for_reduction) {
                if (enc_threads_resolved != orig_threads) {
                    if (verbosity>=2) msg_info("Reduced the number of threads from %u to %u to not exceed the memory usage limit of %llu MiB", orig_threads, enc_threads_resolved, (unsigned long long)ceil_mib(limit_for_reduction));
                }
            } else {
                // still too high with 1 thread MT
                if (userlim) {
                    if (opt_no_adjust) mem_too_low_die(memusage, userlim);
                    msg_warning("Switching to single-threaded mode to not exceed the memory usage limit of %llu MiB", (unsigned long long)ceil_mib(userlim));
                    enc_is_mt_real=false; enc_threads_resolved=1; switched_to_single=true;
                } else {
                    msg_warning("Switching to single-threaded mode to not exceed the memory usage limit of %llu MiB", (unsigned long long)ceil_mib(limit_for_reduction));
                    enc_is_mt_real=false; enc_threads_resolved=1; switched_to_single=true;
                }
            }
        }
    }
    if (!enc_is_mt_real) {
        // single-thread mem check (also for non-xz formats)
        // Only if this path is relevant: if we were originally MT and reduced successfully, enc_is_mt_real would be true.
        uint64_t mem_single = compute_raw_encoder_memusage(resolved_specs[0], resolved_counts[0]);
        if (mem_single==UINT64_MAX) fatal_error("Unsupported filter chain or filter options");
        enc_single_memusage = mem_single;
        if (userlim && mem_single > userlim) {
            if (opt_format==FMT_RAW || opt_no_adjust) mem_too_low_die(mem_single, userlim);
            FilterSpec *lz = chain_find_lzma(resolved_specs[0], resolved_counts[0]);
            if (!lz) mem_too_low_die(mem_single, userlim);
            uint32_t orig_dict = lz->lzma.dict_size;
            while (mem_single > userlim) {
                if (lz->lzma.dict_size <= 1048576U) break;
                lz->lzma.dict_size = ((lz->lzma.dict_size - 1) / 1048576U) * 1048576U;
                mem_single = compute_raw_encoder_memusage(resolved_specs[0], resolved_counts[0]);
            }
            if (mem_single > userlim) mem_too_low_die(mem_single, userlim);
            if (lz->lzma.dict_size != orig_dict) {
                msg_warning("Adjusted LZMA%d dictionary size from %llu MiB to %llu MiB to not exceed the memory usage limit of %llu MiB",
                    lz->id==LZMA_FILTER_LZMA1?1:2,
                    (unsigned long long)(orig_dict>>20), (unsigned long long)(lz->lzma.dict_size>>20), (unsigned long long)ceil_mib(userlim));
            }
            enc_single_memusage = mem_single;
        }
        (void)switched_to_single;
    }
    if (opt_robot) fatal_error("Compression and decompression with --robot are not supported yet.");
    // decide manual
    enc_use_manual_xz = false;
    if (eff==FMT_XZ) {
        if (chain_contains_custom_bcj(resolved_specs[0], resolved_counts[0]) || opt_block_list_set || (opt_block_size_set && !enc_is_mt_real)) enc_use_manual_xz=true;
        // also if any used chain contains custom bcj
        for(int idx=0;idx<10;idx++) if(chain_is_used[idx] && chain_contains_custom_bcj(resolved_specs[idx], resolved_counts[idx])) enc_use_manual_xz=true;
    }
}

