// ---------- suffix / naming ----------
static const char *comp_suffixes_xz[] = {".xz",".txz",NULL};
static const char *comp_suffixes_lzma[] = {".lzma",".tlz",NULL};
static bool ends_with(const char *s, const char *suf){ size_t ls=strlen(s), lf=strlen(suf); return ls>=lf && strcmp(s+ls-lf,suf)==0; }
static const char *base_name_ptr(const char *path){ const char *b=strrchr(path,'/'); return b?b+1:path; }
// suffix match for already-has and for decompress stripping: basename must be longer than suffix
static bool suffix_match_file(const char *filename, const char *suffix){
    const char *base = base_name_ptr(filename);
    if (strlen(base) <= strlen(suffix)) return false;
    return ends_with(filename, suffix);
}
// returns matched suffix string or NULL from list
static const char *find_suffix_in_list(const char *filename, const char **list){
    for(int i=0;list[i];i++) if(suffix_match_file(filename,list[i])) return list[i];
    return NULL;
}
static char *make_dst_compress(const char *src){
    const char *suf;
    if (opt_suffix) suf=opt_suffix;
    else {
        enum Format eff=effective_format();
        suf = (eff==FMT_LZMA)?".lzma":".xz";
        if (opt_format==FMT_RAW) suf=opt_suffix; // required earlier
    }
    char *dst=xmalloc(strlen(src)+strlen(suf)+1); strcpy(dst,src); strcat(dst,suf); return dst;
}
static const char *decomp_known_suffixes[] = {".xz",".txz",".lzma",".tlz",".lz",NULL};
// returns dst or NULL if unknown; caller must free
static char *make_dst_decompress(const char *src, bool *unknown){
    *unknown=false;
    // known list
    for(int i=0;decomp_known_suffixes[i];i++){
        const char *suf=decomp_known_suffixes[i];
        if (suffix_match_file(src,suf)) {
            size_t len=strlen(src)-strlen(suf);
            bool is_tar = (strcmp(suf,".txz")==0 || strcmp(suf,".tlz")==0);
            char *dst=xmalloc(len + (is_tar?5:1));
            memcpy(dst,src,len); dst[len]=0;
            if(is_tar) strcat(dst,".tar");
            return dst;
        }
    }
    if (opt_suffix && suffix_match_file(src,opt_suffix)) {
        size_t len=strlen(src)-strlen(opt_suffix);
        char *dst=xmalloc(len+1); memcpy(dst,src,len); dst[len]=0; return dst;
    }
    *unknown=true; return NULL;
}

// ---------- generic decoder error mapping ----------
static const char *err_msg_for_ret(lzma_ret ret){
    switch(ret){
        case LZMA_FORMAT_ERROR: return "File format not recognized";
        case LZMA_OPTIONS_ERROR: return "Unsupported options";
        case LZMA_DATA_ERROR: return "Compressed data is corrupt";
        case LZMA_MEM_ERROR: return "Cannot allocate memory";
        case LZMA_MEMLIMIT_ERROR: return "Memory usage limit reached";
        case LZMA_BUF_ERROR: return "Unexpected end of input";
        case LZMA_PROG_ERROR: return "Internal error (bug)";
        default: return "Compressed data is corrupt";
    }
}

// Probe structures for XZ header parsing used before opening dst in decompression
typedef struct { int kind; //0 ok recognized, 1 error with msg
    const char *msg;
} ProbeResult;
static uint32_t read_le32(const uint8_t *p){ return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24); }

// manual parse of a block header at data[off], header_size known; validates CRC/filters.
// returns lzma_ret like code: 0 ok, 7 format, 8 options, 9 data
static int parse_block_header_manual(const uint8_t *data, size_t avail, size_t off, uint32_t header_size, FilterSpec *out_filters, int *out_count, uint32_t *out_flags, uint64_t *comp_size_field, uint64_t *uncomp_size_field);
// implementation follows below after helpers

// Check if a given InFile's data is recognized (for unknown suffix case and for dst-exists precedence)
// This consumes peek only (does not consume input logically)
static ProbeResult probe_for_decompress(InFile *in, enum Format fmt_eff);

