// parse VLI from buffer at pos within avail; returns false on invalid
static bool parse_vli_buf(const uint8_t *data, size_t avail, size_t *pos, uint64_t *out){
    uint64_t v=0; int shift=0; size_t start=*pos;
    while (1) {
        if (*pos>=avail) return false;
        if (*pos-start>=9) return false;
        uint8_t b=data[*pos]; (*pos)++;
        v |= (uint64_t)(b&0x7F) << shift;
        if (!(b&0x80)) break;
        if (*pos<avail && data[*pos]==0) return false; // non-canonical as in spec decoder sample (second byte zero)
        // Actually spec decoder: if a continuation byte is 0x00 it's error; the check above covers next byte ==0 after first?
        shift+=7;
    }
    *out=v; return true;
}
static int parse_block_header_manual(const uint8_t *data, size_t avail, size_t off, uint32_t header_size, FilterSpec *out_filters, int *out_count, uint32_t *out_flags, uint64_t *comp_size_field, uint64_t *uncomp_size_field){
    // assume header_size >=8 and off+header_size <= avail (caller ensures)
    const uint8_t *h = data+off;
    // CRC check
    uint32_t stored = read_le32(h+header_size-4);
    uint32_t calc = lzma_crc32(h, header_size-4, 0);
    if (stored != calc) return 9; // data
    uint32_t flags = h[1];
    if (out_flags) *out_flags=flags;
    if (flags & 0x3C) return 9; // reserved bits
    int num_filters = (flags & 0x03) + 1;
    size_t pos=2;
    uint64_t csize = UINT64_MAX, usize_ = UINT64_MAX;
    if (flags & 0x40) { if(!parse_vli_buf(h, header_size-4, &pos, &csize)) return 9; }
    if (flags & 0x80) { if(!parse_vli_buf(h, header_size-4, &pos, &usize_)) return 9; }
    if (comp_size_field) *comp_size_field=csize;
    if (uncomp_size_field) *uncomp_size_field=usize_;
    for(int i=0;i<num_filters;i++){
        uint64_t fid, psize;
        if(!parse_vli_buf(h, header_size-4, &pos, &fid)) return 9;
        if(!parse_vli_buf(h, header_size-4, &pos, &psize)) return 9;
        if (pos+psize > header_size-4) return 9;
        const uint8_t *props = h+pos;
        FilterSpec fs; filter_spec_init(&fs, fid);
        // validate known filters and props
        if (fid==0x03) { // delta
            if(psize!=1) return 8;
            fs.dist = props[0]+1;
        } else if (is_bcj_id(fid)) {
            if(!(psize==0||psize==4)) return 8;
            if(psize==4){ fs.start_offset=read_le32(props); if(fs.start_offset % bcj_alignment(fid)!=0) return 8; }
        } else if (fid==LZMA_FILTER_LZMA2) {
            if(psize!=1) return 8;
            uint32_t bits=props[0];
