    if(memlimit_decompress) lzma_memlimit_set(&strm, memlimit_decompress);
    lzma_ret ret=lzma_raw_decoder(&strm, lf.filters);
    if(ret!=LZMA_OK){ lzma_end(&strm); *out_ret=ret; return false; }
    Buffer transformed; buf_init(&transformed);
    uint8_t obuf[8192];
    strm.next_in=comp_data; strm.avail_in=comp_len;
    do {
        strm.next_out=obuf; strm.avail_out=sizeof obuf;
        ret=lzma_code(&strm, LZMA_RUN);
        if(strm.avail_out<sizeof obuf) buf_append(&transformed, obuf, sizeof obuf - strm.avail_out);
        if(ret==LZMA_STREAM_END) break;
        if(ret!=LZMA_OK){
            // if input exhausted, try finish
            if(strm.avail_in==0){
                // call finish loop
                do {
                    strm.next_out=obuf; strm.avail_out=sizeof obuf;
                    ret=lzma_code(&strm, LZMA_FINISH);
                    if(strm.avail_out<sizeof obuf) buf_append(&transformed, obuf, sizeof obuf - strm.avail_out);
                    if(ret==LZMA_STREAM_END) break;
                    if(ret!=LZMA_OK) break;
                } while(ret!=LZMA_STREAM_END);
                if(ret==LZMA_STREAM_END) break;
            }
            *consumed=strm.total_in; lzma_end(&strm); buf_free(&transformed); *out_ret=ret; return false;
        }
    } while(1);
    *consumed=(size_t)strm.total_in;
    lzma_end(&strm);
    // inverse transforms in reverse order of non-last filters
    for(int i=count-2;i>=0;i--){
        FilterSpec *fs=&specs[i];
        if(fs->id==0x0A) arm64_transform(transformed.data, transformed.len, fs->start_offset, false);
