// ---------- per-file coder processing ----------
static bool process_file_coder(const char *filename, bool from_list, bool is_pseudo_stdin){
    InFile in; memset(&in,0,sizeof in); in.fd=-1;
    OutFile out; memset(&out,0,sizeof out); out.fd=-1;
    Progress pr; memset(&pr,0,sizeof pr);
    bool is_stdin_data=false;
    const char *disp=NULL;
    char *dst_name=NULL;
    bool return_status=false;
    bool progress_started=false;
    // empty filename (CLI only)
    if(!from_list && !is_pseudo_stdin && filename && filename[0]=='\0'){
        msg_error("Empty filename, skipping");
        return false;
    }
    if(is_pseudo_stdin || (!from_list && filename && strcmp(filename,"-")==0)){
        is_stdin_data=true;
    }
    if(is_stdin_data){
        if(opt_files_set && opt_files_name==NULL){
            msg_error("Cannot read data from standard input when reading filenames from standard input");
            return false;
        }
        in.fd=STDIN_FILENO; in.is_stdin=true; in.name=xstrdup("(stdin)"); disp="(stdin)";
        if(fstat(in.fd,&in.st)==0) in.have_stat=true;
    } else {
        disp=filename;
        in.name=xstrdup(filename);
        struct stat lst;
        if(lstat(filename,&lst)!=0){
            msg_error("%s: %s", filename, strerror(errno)); free(in.name); return false;
        }
        bool to_file = !opt_stdout && opt_mode!=MODE_TEST;
        if(S_ISLNK(lst.st_mode) && !opt_force && to_file){
            msg_warning_exit("%s: Is a symbolic link, skipping", filename); free(in.name); return false;
        }
        in.fd=open(filename,O_RDONLY);
        if(in.fd<0){ msg_error("%s: %s", filename, strerror(errno)); free(in.name); return false; }
        if(fstat(in.fd,&in.st)!=0){ msg_error("%s: %s", filename, strerror(errno)); close(in.fd); free(in.name); return false; }
        in.have_stat=true;
        if(S_ISDIR(in.st.st_mode)){ msg_warning_exit("%s: Is a directory, skipping", filename); close(in.fd); free(in.name); return false; }
        if(to_file){
            if(!S_ISREG(in.st.st_mode)){ msg_warning_exit("%s: Not a regular file, skipping", filename); close(in.fd); free(in.name); return false; }
            if(in.st.st_nlink>1 && !opt_force){ msg_warning_exit("%s: Input file has more than one hard link, skipping", filename); close(in.fd); free(in.name); return false; }
        }
    }
    pr.disp_name=(char*)disp;
    pr.is_compress = (opt_mode==MODE_COMPRESS);
    if(in.have_stat && S_ISREG(in.st.st_mode)) pr.total_size=in.st.st_size; else pr.total_size=UINT64_MAX;
    pr.start_time_sec=now_sec();
    // output setup
    if(opt_mode==MODE_TEST){
        out.test_mode=true; out.fd=-1; out.is_stdout=false;
    } else if(is_stdin_data || opt_stdout){
        out.fd=STDOUT_FILENO; out.is_stdout=true; out.name=xstrdup("(stdout)");
    } else {
        // need dst name
        if(opt_mode==MODE_COMPRESS){
            enum Format eff=effective_format();
            const char **suf_list = (eff==FMT_LZMA)?comp_suffixes_lzma:comp_suffixes_xz;
            const char *matched=find_suffix_in_list(filename, suf_list);
            if(matched){
                msg_warning_exit("%s: File already has '%s' suffix, skipping", filename, matched);
