// forward: parsing with pread
static bool read_at(int fd, uint64_t off, void *buf, size_t len){
    uint8_t *p=buf; size_t done=0;
    while(done<len){
        ssize_t r=pread(fd,p+done,len-done,(off_t)(off+done));
        if(r<0){ if(errno==EINTR) continue; return false; }
        if(r==0) return false;
        done+=(size_t)r;
    }
    return true;
}
