    free(rev_streams);
    fi->blocks_len=rev_blocks_len; fi->blocks_cap=rev_blocks_len; fi->blocks=xmalloc(sizeof(BlockInfo)*(rev_blocks_len?rev_blocks_len:1));
    for(size_t i=0;i<rev_blocks_len;i++) fi->blocks[i]=rev_blocks[rev_blocks_len-1-i];
    free(rev_blocks);
    // fill numbers and offsets
    uint64_t total_uncomp_acc=0;
    uint64_t block_total_counter=0;
    size_t block_idx_global=0;
    for(size_t s=0;s<fi->streams_len;s++){
        StreamInfo *si=&fi->streams[s];
        si->stream_num=s+1;
        si->uncomp_offset=total_uncomp_acc;
