    for(size_t i=0;i<fi->blocks_len;i++){
        BlockInfo *bi=&fi->blocks[i];
        // read first byte for header size
        uint8_t first;
        if(!read_at(fd, bi->comp_offset, &first,1)){ *err_msg="Compressed data is corrupt"; return 1; }
        uint32_t hsize=((uint32_t)first+1)*4;
        if(hsize<8 || bi->comp_offset+hsize > bi->comp_offset+bi->unpadded){ // header must fit within unpadded (which includes header+data+check)
            *err_msg="Compressed data is corrupt"; return 1;
        }
        // read header
        uint8_t *hdr=xmalloc(hsize);
        if(!read_at(fd, bi->comp_offset, hdr, hsize)){ free(hdr); *err_msg="Compressed data is corrupt"; return 1; }
        FilterSpec specs[4]; int cnt=0; uint32_t flags=0; uint64_t cfield=UINT64_MAX, ufield=UINT64_MAX;
        int pr=parse_block_header_manual(hdr, hsize, 0, hsize, specs, &cnt, &flags, &cfield, &ufield);
        free(hdr);
        if(pr!=0){ *err_msg=err_msg_for_ret((lzma_ret)pr); return 1; }
        bi->header_size=hsize;
        bi->flags_str[0]=(flags&0x40)?'c':'-'; bi->flags_str[1]=(flags&0x80)?'u':'-'; bi->flags_str[2]=0;
        uint32_t csz=check_size_from_id(bi->check_id);
        if(bi->unpadded < (uint64_t)hsize + csz){ *err_msg="Compressed data is corrupt"; return 1; }
        bi->comp_data_size = bi->unpadded - hsize - csz;
        // checkval
        if(bi->check_id==0){
            bi->checkval_hex=xstrdup("---");
        } else {
            uint8_t *cbytes=xmalloc(csz?csz:1);
            uint64_t coff = bi->comp_offset + bi->unpadded - csz;
            if(!read_at(fd, coff, cbytes, csz)){ free(cbytes); *err_msg="Compressed data is corrupt"; return 1; }
            char *hex=xmalloc(csz*2+1);
            for(uint32_t i=0;i<csz;i++) sprintf(hex+i*2,"%02x",cbytes[i]);
            hex[csz*2]=0; bi->checkval_hex=hex; free(cbytes);
            if(csz>max_check_bytes) max_check_bytes=csz;
        }
        // filters string
        bi->filters_str=format_filter_chain_str(specs,cnt,false);
        // memusage
        // compute using formula described: raw lzma base + 616 + extras
        // Use lib raw for whole chain when possible, then adjust
        uint64_t mem=0;
        if(chain_contains_custom_bcj(specs,cnt)){
