            FilterSpec *lz=chain_find_lzma(specs,cnt);
            if(!lz){ *err_msg="Unsupported options"; return 1; }
            LibFilters lf; build_lib_filters(lz,1,&lf); uint64_t base=lzma_raw_decoder_memusage(lf.filters);
            mem=base+616;
            for(int i=0;i<cnt-1;i++){ if(specs[i].id==0x03) mem+=352; else mem+=1024; }
        } else {
            LibFilters lf;
            if(!build_lib_filters(specs,cnt,&lf)){ *err_msg="Unsupported options"; return 1; }
            uint64_t raw=lzma_raw_decoder_memusage(lf.filters);
            // adjust to match newer lib's constants: +616 and for delta +8 extra
            mem=raw+616;
            for(int i=0;i<cnt;i++) if(specs[i].id==0x03) mem+=8;
        }
        bi->memusage=mem;
        if(mem>fi->mem_needed) fi->mem_needed=mem;
        if(!((flags&0x40)&&(flags&0x80))) fi->sizes_in_headers=false;
