static void version_to_string(uint32_t ver, char *buf, size_t sz){
    // decode encoded version: (((major*1000)+minor)*1000+patch)*10+stability
    uint32_t stability=ver%10; ver/=10; uint32_t patch=ver%1000; ver/=1000; uint32_t minor=ver%1000; uint32_t major=ver/1000;
    (void)stability;
    snprintf(buf,sz,"%u.%u.%u",major,minor,patch);
}
